        [DllImport("gdi32.dll")]static extern uint GetEnhMetaFileBits(IntPtr handle,uint size,byte[] bytes);
        [DllImport("gdi32.dll")]static extern bool DeleteEnhMetaFile(IntPtr handle);
        static void PrintFidelity(PdfDocument doc,PrinterSettings printer,PageSettings page,string directory){
            var options=new PrintOptions{Pages=new[]{0},Sizing=PrintScale.Fit};
            using(var job=PrintEngine.CreateJob(doc,options,printer,page)){var controller=new PreviewPrintController();job.PrintController=controller;job.Print();var result=controller.GetPreviewPageInfo();try{var emf=result[0].Image as Metafile;Assert(emf!=null,"default print output is an enhanced metafile");byte[] bytes;using(var inspect=(Metafile)emf.Clone()){IntPtr native=inspect.GetHenhmetafile();try{bytes=new byte[GetEnhMetaFileBits(native,0,null)];GetEnhMetaFileBits(native,(uint)bytes.Length,bytes);}finally{DeleteEnhMetaFile(native);}}File.WriteAllBytes(Path.Combine(directory,"print-vector.emf"),bytes);int vectors=0,bitmaps=0;for(int at=0;at+8<=bytes.Length;){uint type=BitConverter.ToUInt32(bytes,at),size=BitConverter.ToUInt32(bytes,at+4);if(size<8||at+size>bytes.Length)break;if((type>=2&&type<=8)||(type>=27&&type<=43)||(type>=53&&type<=64)||type==83||type==84||(type>=85&&type<=92)||type==96)vectors++;if(type==76||type==77||type==80||type==81)bitmaps++;at+=(int)size;}Assert(vectors>5,"printer output retains source vector drawing records instead of a page screenshot");log.AppendLine("PRINT RECORDS: "+vectors+" vector, "+bitmaps+" bitmap");
                    var sheet=PrintEngine.Plan(doc,options,page)[0];using(var actual=new Bitmap((int)sheet.Size.Width,(int)sheet.Size.Height))using(var expected=new Bitmap(actual.Width,actual.Height)){using(var g=Graphics.FromImage(actual)){g.Clear(Color.White);g.DrawImage(result[0].Image,new Rectangle(0,0,actual.Width,actual.Height));}using(var g=Graphics.FromImage(expected)){g.Clear(Color.White);PrintEngine.Draw(doc,options,sheet,g,100);}int mismatch=0,ink=0;for(int y=0;y<actual.Height;y+=4)for(int x=0;x<actual.Width;x+=4){Color a=actual.GetPixel(x,y),b=expected.GetPixel(x,y);if(b.R<220||b.G<220||b.B<220){ink++;if(Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B)>140)mismatch++;}}actual.Save(Path.Combine(directory,"print-native.png"),ImageFormat.Png);Assert(ink>300&&mismatch<ink*.15,"native printing matches source colors, placement and page scale");}
                }finally{foreach(var preview in result)preview.Image.Dispose();}}
            options.AsImage=true;options.Dpi=600;using(var job=PrintEngine.CreateJob(doc,options,printer,page)){var controller=new PreviewPrintController();job.PrintController=controller;job.Print();var result=controller.GetPreviewPageInfo();Assert(result.Length==1,"high-resolution image-print fallback remains available");foreach(var preview in result)preview.Image.Dispose();}
        }
        static bool Nearly(float a,float b){return Math.Abs(a-b)<.05f;}
        static void FeaturePrinting(string directory){using(var doc=PdfDocument.Open(Path.Combine(directory,"features.pdf"),"")){
                int[] selected=PrintEngine.SelectPages(8,2,2,"5,1-3,8",0,false);Assert(String.Join(",",selected)=="4,0,1,2,7","print ranges preserve explicit non-contiguous page order");
                Assert(String.Join(",",PrintEngine.SelectPages(8,2,0,"",1,true))=="6,4,2,0","odd-page filtering and reverse order compose correctly");
                Assert(PrintEngine.SelectPages(8,2,1,"",0,false)[0]==2,"current-page printing selects active PDF page");bool empty=false;try{PrintEngine.SelectPages(1,0,0,"",2,false);}catch(InvalidOperationException){empty=true;}Assert(empty,"empty filtered print ranges cannot start a job");
                var printer=new PrinterSettings();foreach(string candidate in PrinterSettings.InstalledPrinters)if(candidate=="Microsoft Print to PDF")printer.PrinterName=candidate;var page=new PageSettings(printer);var options=new PrintOptions{Pages=new[]{0,1,2},MarginMm=0};var plan=PrintEngine.Plan(doc,options,page);
                Assert(plan.Count==3&&plan[0].Items.Count==1,"single-page print plan produces one side per PDF page");var first=plan[0];var item=first.Items[0];Assert(item.Bounds.Left>=first.Area.Left-.1&&item.Bounds.Right<=first.Area.Right+.1&&item.Bounds.Top>=first.Area.Top-.1&&item.Bounds.Bottom<=first.Area.Bottom+.1,"fit printing respects asymmetric hardware printable area");
                Assert(Nearly(item.Bounds.Width,first.Area.Width)||Nearly(item.Bounds.Height,first.Area.Height),"fit printing fills one printable dimension without artificial margins");Assert(!plan[0].Landscape&&plan[2].Landscape,"automatic print orientation follows each PDF page");
                options.Orientation=1;options.Sizing=PrintScale.Actual;var actual=PrintEngine.Plan(doc,options,page)[0].Items[0];Assert(Nearly(actual.Bounds.Width,400*100f/72)&&Nearly(actual.Bounds.Height,600*100f/72),"actual-size printing uses PDF points independent of viewer zoom");
                options.Sizing=PrintScale.Custom;options.Scale=175;var custom=PrintEngine.Plan(doc,options,page)[0].Items[0];Assert(Nearly(custom.Bounds.Width,actual.Bounds.Width*1.75f),"custom print percentage is physically exact");options.Sizing=PrintScale.Shrink;var shrink=PrintEngine.Plan(doc,options,page)[0].Items[0];Assert(shrink.Bounds.Width<=actual.Bounds.Width+.1f,"shrink-only printing never enlarges small pages");
                options.Mode=PrintMode.Multiple;options.Orientation=0;foreach(int per in new[]{2,4,6,9,16}){options.PerSheet=per;var nup=PrintEngine.Plan(doc,options,page);Assert(nup.Count==(3+per-1)/per&&nup[0].Items.Count==Math.Min(3,per),per+"-up print plan groups pages correctly");foreach(var nupSheet in nup)foreach(var placement in nupSheet.Items)Assert(placement.Bounds.Width<=placement.Clip.Width+.1&&placement.Bounds.Height<=placement.Clip.Height+.1,"n-up page stays within its individual cell");}
                options.Pages=new[]{0,1,2,3,4,5,6,7};options.Mode=PrintMode.Booklet;var book=PrintEngine.Plan(doc,options,page);Assert(book.Count==4&&book[0].Items[0].Page==7&&book[0].Items[1].Page==0&&book[1].Items[0].Page==1&&book[1].Items[1].Page==6,"booklet imposes eight pages in correct fold order");
                options.RightBinding=true;var rtl=PrintEngine.Plan(doc,options,page);Assert(rtl[0].Items[0].Page==0&&rtl[0].Items[1].Page==7,"right-bound booklet reverses page pairs");options.RightBinding=false;options.BookletSides=1;Assert(PrintEngine.Plan(doc,options,page).Count==2,"booklet front-only subset supports manual duplex");options.BookletSides=2;Assert(PrintEngine.Plan(doc,options,page)[0].Items[0].Page==1,"booklet back-only subset preserves back-page sequence");options.BookletSides=0;options.Pages=new[]{0,1,2};var padded=PrintEngine.Plan(doc,options,page);Assert(padded.Count==2&&padded[0].Items.Count==1&&padded[1].Items.Count==2,"booklet pads incomplete signatures with blank positions");
                options.Pages=new[]{0};options.Mode=PrintMode.Poster;options.Scale=300;options.OverlapMm=5;var poster=PrintEngine.Plan(doc,options,page);Assert(poster.Count>1&&poster[0].Items[0].Page==poster[1].Items[0].Page,"poster splits a large PDF page into repeated clipped tiles");Assert(poster[1].Items[0].Bounds.Left<poster[0].Items[0].Bounds.Left,"poster tiles advance horizontally with overlap");
                options.Mode=PrintMode.Size;options.Sizing=PrintScale.Fit;options.Scale=100;options.Gray=true;var sheet=PrintEngine.Plan(doc,options,page)[0];using(var image=new Bitmap((int)sheet.Size.Width,(int)sheet.Size.Height)){using(var g=Graphics.FromImage(image)){g.Clear(Color.White);PrintEngine.Draw(doc,options,sheet,g,100);}bool gray=true;int dark=0;for(int y=0;y<image.Height;y+=8)for(int x=0;x<image.Width;x+=8){var c=image.GetPixel(x,y);if(c.R!=c.G||c.G!=c.B)gray=false;if(c.R<200)dark++;}Assert(gray&&dark>50,"grayscale print rendering converts colored source pixels to neutral gray");image.Save(Path.Combine(directory,"print-grayscale.png"),ImageFormat.Png);}
                if(printer.IsValid){PrintFidelity(doc,printer,page,directory);options.Gray=false;options.Mode=PrintMode.Multiple;options.PerSheet=2;options.Pages=new[]{0,1,2};using(var job=PrintEngine.CreateJob(doc,options,printer,page)){var controller=new PreviewPrintController();job.PrintController=controller;job.Print();var output=controller.GetPreviewPageInfo();Assert(output.Length==2&&output[0].Image!=null,"new physical print pipeline produces expected N-up previews without spooling");foreach(var preview in output)preview.Image.Dispose();}}
                using(var form=PdfDocument.Open(Path.Combine(directory,"form.pdf"),"")){int count=N.FPDFPage_GetAnnotCount(form.Page);using(var prepared=form.PreparePrintPage(0,true)){Assert(prepared!=null&&prepared.AllText().Contains("PRESERVED VALUE"),"existing form field appearance is included in printable page content");}Assert(N.FPDFPage_GetAnnotCount(form.Page)==count&&!form.Dirty,"printing form appearances never flattens or changes the open document");form.AddNote(60,220,"PRINT NOTES TEST",Color.Red);using(var prepared=form.PreparePrintPage(0,false)){Assert(prepared.AllText().Contains("PRESERVED VALUE")&&N.FPDFPage_GetAnnotCount(prepared.Page)==0,"excluding annotations still prints existing form appearances");}}
                using(var dialog=new PrintWindow(doc)){dialog.Show();Application.DoEvents();dialog.RefreshForTest();Assert(dialog.HasPreviewForTest,"native print window builds a real document preview");using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(directory,"print-dialog.png"),ImageFormat.Png);}dialog.Close();}
            }}
        static void FeatureStamps(string directory){using(var doc=PdfDocument.Open(Path.Combine(directory,"rotated.pdf"),"")){doc.OpenPage(4);var options=new WatermarkOptions{Pages=new[]{0,1,2,3,4,5,6,7},Text="TEST {page} / {pages}",Angle=35,Opacity=24,Size=30};doc.Watermark(options);Assert(doc.Index==4&&doc.CountWatermarks()==8&&doc.Dirty,"batch watermark restores active page and adds tagged objects on every page");doc.Save(Path.Combine(directory,"watermarked.pdf"));doc.Undo();Assert(doc.CountWatermarks()==0,"one undo removes the entire batch watermark");doc.Redo();Assert(doc.CountWatermarks()==8,"one redo restores batch watermarks");
                options.Text="REPLACED WATERMARK";options.Pages=new[]{0};doc.Watermark(options);Assert(doc.CountWatermarks()==8,"replacing Mini PDF watermarks does not accumulate duplicate objects");doc.Undo();doc.RemoveWatermarks(new[]{0,1,2,3,4,5,6,7});Assert(doc.CountWatermarks()==0&&doc.AllText().Contains("FEATURE PAGE 8"),"removing tagged watermarks preserves original page contents");doc.Save(Path.Combine(directory,"watermarks-removed.pdf"));
                options.Text="平铺测试";options.Pages=new[]{0};options.Tile=true;options.Behind=true;doc.Watermark(options);Assert(doc.CountWatermarks()==9,"Chinese tiled background watermark creates nine tagged text objects");doc.Undo();
                using(var image=new Bitmap(100,40,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.DrawLine(Pens.Navy,4,30,95,8);}options.Image=image;options.Tile=false;options.Behind=false;doc.Watermark(options);Assert(doc.CountWatermarks()==1,"image watermark uses the same tagged reversible workflow");doc.Save(Path.Combine(directory,"image-watermark.pdf"));}
            }
            using(var form=new Form{ClientSize=new Size(660,240)})using(var pad=new SignatureWindow.SignaturePad{Dock=DockStyle.Fill}){form.Controls.Add(pad);form.Show();Application.DoEvents();N.SendMessage(pad.Handle,0x201,new IntPtr(1),Position(new Point(35,90)));for(int x=40;x<550;x+=10)N.SendMessage(pad.Handle,0x200,new IntPtr(1),Position(new Point(x,100+(int)(Math.Sin(x*.03)*35))));N.SendMessage(pad.Handle,0x202,IntPtr.Zero,Position(new Point(550,95)));using(var full=pad.Export())using(var signature=SignatureWindow.Crop(full)){Assert(signature.Width>400&&signature.Height<140&&signature.GetPixel(0,0).A==0,"real left-mouse strokes export tightly cropped transparent signature");using(var doc=PdfDocument.Open(Path.Combine(directory,"features.pdf"),"")){doc.AddImage(signature,new N.Rect(180,35,370,110));doc.Save(Path.Combine(directory,"visible-signature.pdf"));Assert(N.FPDFPage_CountObjects(doc.Page)>3,"visible signature becomes an editable PDF image");}}form.Close();}
        }
        static void FeatureSignatures(string directory){using(var certificate=new X509Certificate2(File.ReadAllBytes(Path.Combine(directory,"signing.pfx")),"minipdf-test",(X509KeyStorageFlags)32)){
                Assert(certificate.HasPrivateKey,"test certificate loads with an ephemeral private key");foreach(string input in new[]{"features.pdf","form.pdf","object-streams.pdf"})using(var doc=PdfDocument.Open(Path.Combine(directory,input),"")){bool before=doc.Dirty;byte[] data=PdfSignatures.Sign(doc,certificate,"TEST ONLY","Local tests");string output=input=="form.pdf"?"signed-form.pdf":input=="object-streams.pdf"?"signed-streams.pdf":"signed.pdf";File.WriteAllBytes(Path.Combine(directory,output),data);Assert(doc.Dirty==before&&doc.SignatureCount==0,"signing creates a separate copy without changing "+input);
                    using(var signed=PdfDocument.FromBytes(data,"")){Assert(signed.SignatureCount==1&&!signed.CanEdit,"signed PDF exposes certificate signature and opens read-only");var reports=PdfSignatures.Inspect(signed);try{Assert(reports.Count==1&&reports[0].Integrity&&reports[0].WholeFile&&!reports[0].Trusted,"cryptographic integrity is distinguished from untrusted test certificate");}finally{PdfSignatures.DisposeReports(reports);}if(input=="features.pdf"){signed.Save(Path.Combine(directory,"signed-copy.pdf"));Assert(Convert.ToBase64String(File.ReadAllBytes(Path.Combine(directory,"signed-copy.pdf")))==Convert.ToBase64String(data),"signed Save As preserves original signature bytes");bool rejected=false;try{signed.AddText("NOT ALLOWED",20,20,12,"自动",Color.Black);}catch(InvalidOperationException){rejected=true;}Assert(rejected&&!signed.Dirty,"editing a signed PDF is blocked without invalidating its signature");}}
                    if(input=="features.pdf"){var tamper=(byte[])data.Clone();tamper[7]=tamper[7]=='7'?(byte)'6':(byte)'7';using(var altered=PdfDocument.FromBytes(tamper,"")){var reports=PdfSignatures.Inspect(altered);try{Assert(!reports[0].Integrity,"a one-byte change is detected by signature verification");}finally{PdfSignatures.DisposeReports(reports);}}var later=new byte[data.Length+18];Array.Copy(data,later,data.Length);Array.Copy(System.Text.Encoding.ASCII.GetBytes("\n% LATER REVISION\n"),0,later,data.Length,18);using(var amended=PdfDocument.FromBytes(later,"")){var reports=PdfSignatures.Inspect(amended);try{Assert(reports[0].Integrity&&!reports[0].WholeFile,"later bytes are flagged as unverified changes to signed file");}finally{PdfSignatures.DisposeReports(reports);}}}
                }
                using(var expired=new X509Certificate2(File.ReadAllBytes(Path.Combine(directory,"expired.pfx")),"minipdf-test",(X509KeyStorageFlags)32)){bool refused=false;try{PdfSignatures.CheckCertificate(expired);}catch(InvalidOperationException){refused=true;}Assert(refused,"expired signing certificates are rejected");}using(var publicOnly=new X509Certificate2(Path.Combine(directory,"signing.cer"))){bool refused=false;try{PdfSignatures.CheckCertificate(publicOnly);}catch(InvalidOperationException){refused=true;}Assert(refused,"certificates without private keys cannot sign");}
            }}
        static void FeatureMergeAndPan(string directory){using(var plan=new MergePlan()){
                var first=PdfDocument.Open(Path.Combine(directory,"features.pdf"),"");first.Extract(new[]{0,1,2},Path.Combine(directory,"merge-a.pdf"));first.Extract(new[]{3,4,5,6,7},Path.Combine(directory,"merge-b.pdf"));first.Dispose();plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-a.pdf"),""),"A.pdf");plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-b.pdf"),""),"B.pdf");Assert(plan.Count==8&&plan.Groups.Count==2,"combine workspace stores independent files and page references");
                plan.MoveGroup(plan.Groups[1],0);Assert(plan.Groups[0].Name=="B.pdf","file groups can move before another file group");var moved=plan.Groups[0].Pages[2];plan.MovePage(moved,plan.Groups[1],plan.Groups[1].Pages.Count);Assert(plan.Groups[1].Pages[3].Index==2&&plan.Groups[1].Pages[3].Source==moved.Source,"page can move between arbitrary file groups");plan.Undo();Assert(plan.Groups[0].Pages.Count==5&&plan.Groups[1].Pages.Count==3,"combine reorder undo restores page grouping");
                // B: 4,5,6,7,8; A: 1,2,3 -> B: 4,5; A: 1,2,3,6,7,8.
                for(int i=0;i<3;i++)plan.MovePage(plan.Groups[0].Pages[2],plan.Groups[1],plan.Groups[1].Pages.Count);plan.Change(delegate{plan.Groups[0].Pages[0].Rotation=1;});using(var combined=plan.Build()){Assert(combined.Count==8&&combined.Dirty,"combine generates a new unsaved document");combined.Save(Path.Combine(directory,"combined.pdf"));Assert(combined.AllText().IndexOf("FEATURE PAGE 4",StringComparison.Ordinal)<combined.AllText().IndexOf("FEATURE PAGE 1",StringComparison.Ordinal),"merged PDF follows the user-selected file and page order");}Assert(plan.Groups[0].Pages[0].Source.SignatureCount==0,"combining does not replace or modify source files");
                using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-a.pdf"),""),"A.pdf");dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-b.pdf"),""),"B.pdf");dialog.Show();Application.DoEvents();foreach(Control child in dialog.Controls){var board=child as MergeWindow.MergeBoard;if(board==null)continue;board.Rebuild();dialog.Plan.Groups[0].Expanded=true;board.Rebuild();N.SendMessage(board.Handle,0x201,new IntPtr(1),Position(new Point(85,95)));N.SendMessage(board.Handle,0x200,new IntPtr(1),Position(new Point(350,95)));N.SendMessage(board.Handle,0x202,IntPtr.Zero,Position(new Point(350,95)));Assert(dialog.Plan.Groups[0].Pages[1].Index==0,"real left-mouse drag reorders expanded page thumbnails");}using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(directory,"combine-dialog.png"),ImageFormat.Png);}dialog.DialogResult=DialogResult.OK;dialog.Close();}
            }
            using(var form=new MainWindow(null)){form.LoadForTest(PdfDocument.Open(Path.Combine(directory,"features.pdf"),""));form.Show();Application.DoEvents();form.ApplyZoom("250%");var view=form.CanvasForTest;view.AutoScrollPosition=new Point(250,300);var before=view.AutoScrollPosition;form.SetTool(Tool.Hand);Mouse(view,new Point(250,220),new Point(185,165));Assert(view.AutoScrollPosition.X<before.X&&view.AutoScrollPosition.Y<before.Y&&!form.Document.Dirty,"hand tool pans enlarged pages horizontally and vertically with the left mouse");
                var hand=(ToolStripButton)typeof(MainWindow).GetField("handQuick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(form);var select=(ToolStripButton)typeof(MainWindow).GetField("selectQuick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(form);select.PerformClick();Assert(view.Mode==Tool.Read&&select.Checked&&!hand.Checked,"visible Select button exits hand tool and updates checked state");Command(form,Keys.H);Assert(view.Mode==Tool.Hand&&hand.Checked,"H enters hand tool when reading area has focus");Command(form,Keys.V);Assert(view.Mode==Tool.Read&&select.Checked,"V returns to text selection");hand.PerformClick();Command(form,Keys.Escape);Assert(view.Mode==Tool.Read&&!hand.Checked,"Esc exits hand tool");before=view.AutoScrollPosition;N.SendMessage(view.Handle,0x100,new IntPtr((int)Keys.Space),IntPtr.Zero);Mouse(view,new Point(250,220),new Point(200,180));N.SendMessage(view.Handle,0x101,new IntPtr((int)Keys.Space),IntPtr.Zero);Assert(view.AutoScrollPosition.X<before.X&&view.Mode==Tool.Read&&!form.Document.Dirty,"holding Space temporarily pans without changing reading tool or PDF");form.Close();}
        }
        static void FeaturePageManagement(string directory){using(var doc=PdfDocument.Open(Path.Combine(directory,"external.pdf"),""))using(var original=PdfDocument.FromBytes(doc.Serialize(false),"")){
                var pages=new List<MergePage>{new MergePage{Source=original,Index=2,Rotation=1},new MergePage{Source=original,Index=0},new MergePage{Source=original,Index=1}};doc.Organize(pages,original);Assert(doc.Count==3&&doc.Index==1&&doc.Dirty,"page organizer reorders existing pages while keeping the active page");Assert(doc.Bookmarks().Count==3&&doc.Bookmarks()[0].Page==1&&doc.Bookmarks()[2].Page==0,"page organizer preserves bookmarks attached to retained page objects");doc.OpenPage(0);Assert(N.FPDFPage_GetRotation(doc.Page)==1,"page organizer applies requested rotation");doc.Undo();Assert(doc.Index==0&&doc.Bookmarks()[0].Page==0,"all page organization changes undo in one step");
                pages.RemoveAt(2);pages.Add(new MergePage{Source=original,Index=0});doc.Organize(pages,original);Assert(doc.Count==3&&doc.AllText().Split(new[]{"EXTERNAL PAGE 1"},StringSplitOptions.None).Length==3,"page organizer supports duplicate pages and removal in one transaction");doc.Undo();Assert(doc.Count==3&&doc.AllText().Contains("EXTERNAL PAGE 2"),"undo restores deleted pages and removes duplicates");
                bool empty=false;try{doc.Organize(new List<MergePage>(),original);}catch(InvalidOperationException){empty=true;}Assert(empty&&doc.Count==3,"organizer cannot remove the last page");
            }
            using(var form=new MainWindow(null)){form.LoadForTest(PdfDocument.Open(Path.Combine(directory,"baseline.pdf"),""));form.Show();Application.DoEvents();var doc=form.Document;var view=form.CanvasForTest;view.TextStart=0;view.TextCount=16;int before=N.FPDFPage_GetAnnotCount(doc.Page);form.HighlightSelection(Color.FromArgb(90,205,160));Assert(N.FPDFPage_GetAnnotCount(doc.Page)==before+1,"selected text highlights directly without drawing a separate rectangle");IntPtr annot=N.FPDFPage_GetAnnot(doc.Page,before);try{Assert(N.FPDFAnnot_GetSubtype(annot)==9,"text selection creates a standard PDF highlight annotation");}finally{N.FPDFPage_CloseAnnot(annot);}doc.Save(Path.Combine(directory,"selected-highlight.pdf"));doc.Undo();Assert(N.FPDFPage_GetAnnotCount(doc.Page)==before,"text selection highlight can be undone");
                bool palette=false;view.TextStart=0;view.TextCount=12;using(var menu=form.BuildContext(new Point(80,80)))foreach(ToolStripItem item in menu.Items){var sub=item as ToolStripMenuItem;if(sub!=null&&sub.DropDownItems.Count>=14)palette=true;}Assert(palette,"selection context menu exposes twelve highlight colors plus custom color");form.SetTool(Tool.Read);form.Close();}
            using(var plan=new MergePlan()){plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-a.pdf"),""),"A");plan.Add(PdfDocument.Open(Path.Combine(directory,"merge-b.pdf"),""),"B");var moving=new List<MergePage>{plan.Groups[0].Pages[0],plan.Groups[0].Pages[2]};plan.MovePages(moving,plan.Groups[1],1);Assert(plan.Groups[0].Pages.Count==1&&plan.Groups[1].Pages[1]==moving[0]&&plan.Groups[1].Pages[2]==moving[1],"multi-page dragging preserves selection order across file groups");plan.Undo();Assert(plan.Groups[0].Pages.Count==3&&plan.Groups[1].Pages.Count==5,"multi-page drag is one undoable operation");plan.Redo();Assert(plan.Groups[0].Pages.Count==1,"multi-page drag can be redone");}
        }
        static void FeatureDialogUi(string directory){UiText.English=true;using(var doc=PdfDocument.Open(Path.Combine(directory,"features.pdf"),""))foreach(Form dialog in new Form[]{new SignatureWindow(),new WatermarkWindow(doc),new CertificateWindow()})using(dialog){dialog.Show();Application.DoEvents();bool translated=true;var pending=new Queue<Control>();pending.Enqueue(dialog);while(pending.Count>0){var control=pending.Dequeue();if(System.Text.RegularExpressions.Regex.IsMatch(control.Text,"[\\u4e00-\\u9fff]"))translated=false;foreach(Control child in control.Controls)pending.Enqueue(child);}Assert(translated,"new "+dialog.Text+" window exposes English controls");using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(directory,dialog is SignatureWindow?"signature-dialog.png":dialog is WatermarkWindow?"watermark-dialog.png":"certificate-dialog.png"),ImageFormat.Png);}dialog.Close();}}
        static void Features(string directory){if(!File.Exists(Path.Combine(directory,"features.pdf"))||!File.Exists(Path.Combine(directory,"external.pdf"))){log.AppendLine("SKIP: advanced fixtures missing; run verify_pdf.py fixtures and verify_features.py fixtures first");return;}FeaturePrinting(directory);FeatureStamps(directory);FeatureSignatures(directory);FeatureMergeAndPan(directory);FeaturePageManagement(directory);FeatureDialogUi(directory);SignatureAndWatermarkFixes(directory);MergeDetails(directory);}
        internal static int RunFeatures(string directory){logPath=Path.Combine(directory,"feature-test.txt");try{Features(directory);log.AppendLine("TOTAL: "+assertions+" assertions, 0 failures");File.WriteAllText(logPath,log.ToString());return 0;}catch(Exception e){log.AppendLine(e.ToString());File.WriteAllText(logPath,log.ToString());return 1;}}
    }
